有关下面 C++代码说法错误的是（ ）。
int factA(int n) {
    if (n <= 1)
        return 1;
    int ret = 1;
    for (int i = 2; i <= n; ++i)
        ret *= i;
    return ret;
}
int factB(int n) {
    return n == 1 ? 1 : n * factB(n - 1);
}
int main() {
    int n;
    cin >> n;
    cout << factA(n) << ' ' << factB(n) << endl;
    return 0;
}

下面 C++代码意在实现字符串反序的功能。关于这段代码，以下说法正确的是（ ）
void printSReverse(char* sIn, int len) {
    if (len <= 1) {
        cout << sIn[0];
    }
    else {
        cout << sIn[0];
        printSReverse(sIn + 1, len - 1);
    }
}
int main() {
    char sIn[100] = "Hello";
    printSReverse(sIn, strlen(sIn));
    return 0;
}

阅读下面 C++实现的二分查找代码，下列说法中错误的是（ ）。
int binarySearch(int * arr, int l, int r, int x) {
    if (r >= l) {
        int mid = l + (r - l) / 2;
        if (arr[mid] == x)
            return mid;
        else if (arr[mid] > x)
            return binarySearch(arr, l, mid - 1, x);
        else
            return binarySearch(arr, mid + 1, r, x);
    }
    else
        return -1;
}

